foreach ($f in (Get-ChildItem -Recurse -Path src -Include *.ts,*.tsx)) { $c = Get-Content $f.FullName -Raw; if ($c.Contains('${API_ORIGIN}') -and -not $c.Contains('apiConfig')) { $lines = Get-Content $f.FullName; $lastImport = 0; for ($i = 0; $i -lt $lines.Count; $i++) { if ($lines[$i] -match '^import ') { $lastImport = $i } }; $rel = $f.DirectoryName.Substring($PWD.Path.Length + 1) -replace '\\','/'; $importLine = "import { API_ORIGIN } from `"/$rel/apiConfig`"; $newLines = @($lines[0..$lastImport]) + $importLine + @($lines[($lastImport+1)..($lines.Count-1)]); Set-Content $f.FullName ($newLines -join "`r`n") -NoNewline; Write-Output "import added: $($f.Name)" }
